        0.4405093f,0.6609393f,0.04176272f,0.7157372f,-0.08236364f,-0.6199088f,0.9827793f,0.0219783f,
        0.1237301f,0.007619964f,0.6512711f,0.2144148f
    )

    private val FLT_W2 = floatArrayOf(
        -1.600526f,-0.09790171f,0.7905146f,0.1414597f,1.156839f,-1.626989f,-0.7122273f,1.188186f,0.8704957f,0.1425698f,-0.6858326f,-0.4378367f,
        0.5446449f,-2.545717f,-0.5218695f,0.6936586f,0.2367576f,-0.3475188f,0.1677898f,-0.3898808f,-0.339651f,-0.5273843f,-1.716579f,0.8950096f,
        -1.673473f,0.03594311f,-0.6439815f,1.32761f,0.1263556f,-1.541448f,-1.050311f,-0.3328863f,0.3930524f,-0.7934046f,0.04644826f,0.8100328f,
        1.977027f,-0.2450766f,0.3867386f,-1.03986f,-0.8764627f,1.801188f,0.9036421f,-0.5516045f,-1.119973f,0.03865478f,1.094125f,-1.217345f
    )
    private val FLT_B2 = floatArrayOf(-0.3526176f,-0.2600968f,-0.8637617f,0.1524518f)

    /**
     * Executes dense feedforward MLP and returns argmax class index.
     */
    private fun denseArgmax(
        x: FloatArray,
        inSizes: IntArray,
        outSizes: IntArray,
        weights: Array<FloatArray>,
        biases: Array<FloatArray>
    ): Pair<Int, FloatArray> {
        var a = x.copyOf()
        for (l in inSizes.indices) {
            val inD = inSizes[l]
            val outD = outSizes[l]
            val w = weights[l]
            val b = biases[l]
            val z = FloatArray(outD)

            for (o in 0 until outD) {
                var s = b[o]
                val offset = o * inD
                for (i in 0 until inD) {
                    s += w[offset + i] * a[i]
                }
                // ReLU activation on hidden layers, linear on output layer
                z[o] = if (l < inSizes.size - 1) max(0f, s) else s
            }
            a = z
        }

        var bestIdx = 0
        for (o in 1 until a.size) {
            if (a[o] > a[bestIdx]) {
                bestIdx = o
            }
        }
        return Pair(bestIdx, a)
    }

    /**
     * Predicts advice class and fault class from raw 15-feature telemetry vector.
     */
    fun predict(rawFeatures: FloatArray): PredictionOutput {
        require(rawFeatures.size == N_FEAT) { "Input must contain exactly $N_FEAT features." }

        // Standardize features
        val xNorm = FloatArray(N_FEAT)
        for (i in 0 until N_FEAT) {
            xNorm[i] = (rawFeatures[i] - MEAN[i]) / STD[i]
        }

        // Advice Head: 15 -> 16 -> 12 -> 4
        val inAdv = intArrayOf(15, 16, 12)
        val outAdv = intArrayOf(16, 12, 4)
        val (advIdx, advLogits) = denseArgmax(
            xNorm,
            inAdv,
            outAdv,
            arrayOf(ADV_W0, ADV_W1, ADV_W2),
            arrayOf(ADV_B0, ADV_B1, ADV_B2)
        )

        // Fault Head: 15 -> 16 -> 12 -> 4
        val inFlt = intArrayOf(15, 16, 12)
        val outFlt = intArrayOf(16, 12, 4)
        val (fltIdx, fltLogits) = denseArgmax(
            xNorm,
            inFlt,
            outFlt,
            arrayOf(FLT_W0, FLT_W1, FLT_W2),
            arrayOf(FLT_B0, FLT_B1, FLT_B2)
        )

        val adviceClass = ADVICE_CLASSES[advIdx.coerceIn(ADVICE_CLASSES.indices)]
        val faultClass = FAULTS_SAFE(fltIdx)

        return PredictionOutput(
            advice = adviceClass,
            adviceText = ADVICE_DESCRIPTIONS[adviceClass] ?: "Optimal condition.",
            fault = faultClass,
            faultText = FAULT_DESCRIPTIONS[faultClass] ?: "No hardware faults detected.",
            adviceIndex = advIdx,
            faultIndex = fltIdx,
            logitsAdvice = advLogits,
            logitsFault = fltLogits
        )
    }

    private fun FAULTS_SAFE(idx: Int): String {
        return FAULT_CLASSES.getOrElse(idx) { "NONE" }
    }

    /**
     * Helper to construct 15 features from standard cold storage telemetry.
     */
    fun buildFeatures(
        temp: Double,
        ambient: Double,
        solarKw: Double,
        soc: Double,
        hour: Double,
        compOn: Boolean,
        doorOpen: Boolean,
        dtemp15m: Double = 0.0,
        dtemp60m: Double = 0.1,
        tempStd60m: Double = 0.45,
        dsoc60m: Double = 0.02,
        compDuty60m: Double = 0.45,
        doorStreak: Double = 0.0,
        doorFrac60m: Double = 0.05
    ): FloatArray {
        val hRad = 2.0 * Math.PI * hour / 24.0
        val compKw = if (compOn) 0.60 else 0.0

        return floatArrayOf(
            temp.toFloat(),
            dtemp15m.toFloat(),
            dtemp60m.toFloat(),
            tempStd60m.toFloat(),
            ambient.toFloat(),
            solarKw.toFloat(),
            soc.toFloat(),
            dsoc60m.toFloat(),
            sin(hRad).toFloat(),
            cos(hRad).toFloat(),
            compDuty60m.toFloat(),
            compKw.toFloat(),
            (if (doorOpen) 1.0f else 0.0f),
            doorStreak.toFloat(),
            doorFrac60m.toFloat()
        )
    }

    data class PredictionOutput(
        val advice: String,
        val adviceText: String,
        val fault: String,
        val faultText: String,
        val adviceIndex: Int,
        val faultIndex: Int,
        val logitsAdvice: FloatArray,
        val logitsFault: FloatArray
    )
}
